dict(id='B03', act=0, set='nana6', vis='Nana pulls out a battered tin recipe box labelled THINGS NOBODY TELLS YOU. Ten index cards fan out across the table, one icon on each.',
  lines=[('N', "Nana June spent forty-one years behind a bank counter. She has watched people win and lose money in every way there is. And she says almost all of it comes down to ten ideas nobody teaches you. Taxes. Banks. Interest. Inflation. Recessions. Credit scores. Money itself. Investing. Value. And time."),
         ('NANA', "Sit down. We're doing all ten. Tonight.")]),
dict(id='B04', act=0, card="10 Money Concepts", sub="Nobody explains"),
